package release

// S4g acceptance (protected, written by Claude): the member digest contract shared with the
// Harness. testdata/canonical_vectors.json was generated by encoding/json; the Harness test
// harness/tests/publish/test_canonical.py checks its own canonical form against the same file,
// so either side drifting from the frozen S3b digest definition fails a test.

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestCanonicalDigestMatchesTheSharedVectors(t *testing.T) {
	raw, err := os.ReadFile("testdata/canonical_vectors.json")
	require.NoError(t, err)
	var vectors []struct {
		Name      string          `json:"name"`
		Payload   json.RawMessage `json:"payload"`
		Canonical string          `json:"canonical"`
		Digest    string          `json:"digest"`
	}
	require.NoError(t, json.Unmarshal(raw, &vectors))
	require.NotEmpty(t, vectors)
	for _, v := range vectors {
		t.Run(v.Name, func(t *testing.T) {
			var payload any
			require.NoError(t, json.Unmarshal(v.Payload, &payload))
			canonical, err := json.Marshal(payload)
			require.NoError(t, err)
			require.Equal(t, v.Canonical, string(canonical))
			require.Equal(t, v.Digest, canonicalDigest(payload))
		})
	}
}
